<?php
require dirname(__DIR__,2).'/app/documents.php';$u=require_user();$admin=$u['role']==='admin';$uid=$admin?(int)($_GET['user']??$u['id']):(int)$u['id'];$filename='statement.pdf';
if(isset($_GET['preview'])){if(!$admin)json_out(['error'=>'Admin access required.'],403);$lines=['INVOICE PREVIEW','Billed to: Example Client','Date: '.gmdate('Y-m-d'),'Order: #123','Amount: EUR 50.00','This is a theme preview, not a financial transaction.'];}
elseif(isset($_GET['order'])){[$o,$lines]=tdc_invoice((int)$_GET['order']);if(!$admin&&(int)$o['user_id']!==$uid)json_out(['error'=>'Document not found.'],404);$filename='INV-'.$o['id'].'.pdf';}
elseif(isset($_GET['withdraw'])){$q=db()->prepare('SELECT * FROM royalty_withdrawals WHERE id=?');$q->execute([(int)$_GET['withdraw']]);$w=$q->fetch();if(!$w||(!$admin&&(int)$w['user_id']!==$uid)||$w['status']!=='paid')json_out(['error'=>'Paid payout receipt not found.'],404);$lines=['PAYOUT RECEIPT #'.$w['id'],'Beneficiary: '.$w['beneficiary'],'Method/network: '.$w['method'],'Amount: EUR '.number_format((float)$w['amount'],2),'External reference: '.$w['payment_reference'],'Status: Paid','Date: '.$w['updated_at']];$filename='PAYOUT-'.$w['id'].'.pdf';}
else{$q=db()->prepare('SELECT r.*,u.name FROM users u LEFT JOIN artist_reports r ON r.user_id=u.id WHERE u.id=?');$q->execute([$uid]);$r=$q->fetch();if(!$r)json_out(['error'=>'Customer not found.'],404);$q=db()->prepare('SELECT amount,note,created_at FROM royalty_ledger WHERE user_id=? ORDER BY id DESC');$q->execute([$uid]);$rows=$q->fetchAll();$lines=['ROYALTY STATEMENT',$r['name'],'Generated: '.gmdate('Y-m-d H:i').' UTC','Tracks: '.($r['tracks']??0),'Streams: '.($r['streams']??0),'Earnings: EUR '.number_format((float)($r['earnings']??0),2),'Available: EUR '.number_format(array_sum(array_column($rows,'amount')),2),'','Ledger'];foreach($rows as $row)$lines[]=$row['created_at'].' | EUR '.$row['amount'].' | '.$row['note'];if(($_GET['format']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="royalties.csv"');$out=fopen('php://output','w');fputcsv($out,['Date','EUR','Description']);foreach($rows as $row){$note=$row['note'];if(preg_match('/^[=+@\-]/',$note))$note="'".$note;fputcsv($out,[$row['created_at'],$row['amount'],$note]);}exit;}}
header('Cache-Control: private, no-store');header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$filename.'"');echo tdc_pdf($lines);
